/// the curl invocation and inter-attempt sleep inside.
class DownloadLoop {
  DownloadLoop({
    required this.header,
    required this.body,
    required this.attempts,
    required this.curl,
    required this.sleepSeconds,
  });

  /// One curl invocation, backslash continuations joined.
  final String curl;
  final String header;
  final String body;
  final int attempts;
  final int sleepSeconds;

  static DownloadLoop parse(String runText) {
    final lines = runText.split('\n');
    final headerIndex =
        lines.indexWhere((l) => RegExp(r'^\s*for\s+\w+\s+in\s+').hasMatch(l));
