        run.contains('/tmp/WasmRun.xcframework.zip'),
        isFalse,
        reason:
            'the arch-less /tmp/WasmRun.xcframework.zip path must not come '
            'back anywhere in the step — it is the shared-race path '
            '(gh-1149 review)',
      );
