      // computed from the release download.
      const digest =
          'aca903d732202bcdf9c8d19fbb8a795c3c930762419f852a5ee228468c548a98';
      expect(
        run,
        contains('echo "$digest  \$ZIP" | shasum -a 256 -c -'),
        reason:
